class Solution {
public:
    Node* insert(Node* head, int insertVal) {
        Node* node = new Node(insertVal);
        if (!head) {
            node->next = node;
            return node;
        }
        Node* cur = head;
        while (true) {
            Node* next = cur->next;
            bool middle = cur->val <= insertVal && insertVal <= next->val;
            bool wrap = cur->val > next->val
                     && (insertVal >= cur->val || insertVal <= next->val);
            if (middle || wrap || next == head) {
                cur->next = node;
                node->next = next;
                return head;
            }
            cur = next;
        }
    }
};
